  ('33333333-3333-3333-3333-000000000002', 'SEC (Securities and Exchange Commission) eSPARC portal', 'https://esparc.sec.gov.ph/application/name-verification', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000003', 'Barangay Requirements based on San Antonio, Pasig (confirmed by AsikaGo research, Oct 5, 2026)', 'https://www.facebook.com/share/p/1ecMBm3Tu7/', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000004', 'Pasig City CLIMA Portal, Certificate of Conformance', 'https://clima.pasigcity.gov.ph/clima/PublicConformance', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000005', 'BFP (Bureau of Fire Protection) Fire Safety Inspection System', 'https://fsis.e-bfp.com/', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000006', 'Pasig BPLD (Business Permits and Licensing Department) Unified Business Application Form', 'https://assets.pasigcity.gov.ph/storage/downloadables/2024/12/27/676eb0e3d77c11735307491BPLD%20UAF%20Final.pdf', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000007', 'Pasig City downloadable forms and requirements list', 'https://pasigcity.gov.ph/downloadable-forms', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000008', 'Pasig City Health Department, Environmental Sanitation Section', 'https://assets.pasigcity.gov.ph/storage/attachments/pasig_city_health_department/633e8116ded771665040662EDITED%20CHO%20Environmental%20Sanitation%20Section.pdf', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000009', 'Pasig BPLD and BOSS (Business One-Stop Shop) (confirmed by AsikaGo research, Oct 5, 2026)', 'https://pasigcity.gov.ph/services', DATE '2026-10-05'),
  ('33333333-3333-3333-3333-000000000010', 'BIR (Bureau of Internal Revenue) Online Registration and Update System (ORUS)', 'https://orus.bir.gov.ph/', DATE '2026-10-08'),
  ('33333333-3333-3333-3333-000000000011', 'BIR (Bureau of Internal Revenue) Form 1901 for sole proprietors', 'https://bir-cdn.bir.gov.ph/BIR/pdf/1901%20October%202025%20ENCS%20Final.pdf', DATE '2026-10-08'),
  ('33333333-3333-3333-3333-000000000012', 'BIR (Bureau of Internal Revenue) Form 1903 for corporations and partnerships', 'https://bir-cdn.bir.gov.ph/BIR/pdf/1903%20October%202025%20ENCS%20-%20Final.pdf', DATE '2026-10-08');
INSERT INTO registration_steps (id, name, agency, description, actions, condition_note) VALUES
  ('44444444-4444-4444-4444-00000000001a', 'DTI Business Name Registration', 'DTI (Department of Trade and Industry)', 'This gives your business name legal protection. It is for people who run a business alone, as a sole proprietor.', 'Go to the DTI BNRS (Business Name Registration System) website.
INSERT INTO requirements (id, step_id, name, description, source_id) VALUES
  ('55555555-5555-5555-5555-00000001a001', '44444444-4444-4444-4444-00000000001a', 'Filipino citizen, at least 18 years old', 'You must be a Filipino citizen and 18 years old or older.', '33333333-3333-3333-3333-000000000001'),
  ('55555555-5555-5555-5555-00000001a002', '44444444-4444-4444-4444-00000000001a', 'One valid government ID', 'For example a passport, driver''s license, or UMID.', '33333333-3333-3333-3333-000000000001'),
  ('55555555-5555-5555-5555-00000001a003', '44444444-4444-4444-4444-00000000001a', '2 or 3 business names', 'Pick backup names in case your first choice is taken.', '33333333-3333-3333-3333-000000000001'),
  ('55555555-5555-5555-5555-00000001a004', '44444444-4444-4444-4444-00000000001a', 'Email address and mobile number', 'Use ones you check often. Your certificate is sent to your email.', '33333333-3333-3333-3333-000000000001'),
  ('55555555-5555-5555-5555-00000001a005', '44444444-4444-4444-4444-00000000001a', 'Registration fee', 'Barangay ₱200, City ₱500, Region ₱1,000, Nation ₱2,000. Add ₱30 for the documentary stamp tax. Pay within 7 days or the application is cancelled.', '33333333-3333-3333-3333-000000000001'),
  ('55555555-5555-5555-5555-00000001b001', '44444444-4444-4444-4444-00000000001b', 'Company name', 'Check it is free to use on the SEC eSPARC website.', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-00000001b002', '44444444-4444-4444-4444-00000000001b', 'Articles and By-Laws', 'The website makes these for you. Download, sign, and upload them.', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-00000001b003', '44444444-4444-4444-4444-00000000001b', 'Articles of Partnership', 'The website makes this for you. Download, sign, and upload it.', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-00000001b004', '44444444-4444-4444-4444-00000000001b', 'Treasurer''s Affidavit and proof of paid-up capital', 'A paper from the treasurer and a bank certificate, if they apply to you.', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-00000001b005', '44444444-4444-4444-4444-00000000001b', 'Valid IDs and TIN of every owner', 'Each person who starts the company needs a valid government ID and a TIN (Tax Identification Number).', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-00000001b006', '44444444-4444-4444-4444-00000000001b', 'SEC registration fee', 'The fee depends on your company type and capital. The website shows your exact amount.', '33333333-3333-3333-3333-000000000002'),
  ('55555555-5555-5555-5555-000000002001', '44444444-4444-4444-4444-000000000002', 'Barangay clearance for renovation', 'If you did not renovate, bring a Certificate of Non-Renovation from the building administrator instead.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000002002', '44444444-4444-4444-4444-000000000002', 'Copy of your DTI or SEC registration', 'Bring your DTI certificate, or your SEC certificate with Articles and By-Laws.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000002003', '44444444-4444-4444-4444-000000000002', 'Contract of lease or land title', 'Bring your lease contract, or the Transfer Certificate of Title (TCT) if you own the place.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000002004', '44444444-4444-4444-4444-000000000002', 'Business insurance policy', 'A Comprehensive General Liability (CGL) insurance policy for your business.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000002005', '44444444-4444-4444-4444-000000000002', 'Space use fee', '₱12.10 for every square meter. The lowest fee is ₱121. Confirm the exact amount at your barangay hall.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000002006', '44444444-4444-4444-4444-000000000002', 'Business plate fee', '₱220. Confirm the exact amount at your barangay hall.', '33333333-3333-3333-3333-000000000003'),
  ('55555555-5555-5555-5555-000000003001', '44444444-4444-4444-4444-000000000003', 'Tax Declaration of land and building', 'An updated copy from the owner of the place.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003002', '44444444-4444-4444-4444-000000000003', 'Lease agreement', 'A notarized agreement between you and the owner, with IDs. If you rent from someone who is not the owner, bring the sub-lease and the owner''s contract. If you use the place for free, bring a notarized Affidavit of No Rental from the owner.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003003', '44444444-4444-4444-4444-000000000003', 'Authorization letter or SPA', 'A notarized letter or Special Power of Attorney, only if someone else applies for you.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003004', '44444444-4444-4444-4444-000000000003', 'Barangay clearance', 'The one you got in Step 2.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003005', '44444444-4444-4444-4444-000000000003', 'Occupancy Permit', 'Only if your building was built after 2020.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003006', '44444444-4444-4444-4444-000000000003', 'Certificate of No Objection', 'From the homeowners'' association or building administrator, if your place is inside a condominium.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003007', '44444444-4444-4444-4444-000000000003', 'Photos of your business place', 'One photo of the inside and one of the outside.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000003008', '44444444-4444-4444-4444-000000000003', 'Google Map of your place', 'Show the exact location of your business.', '33333333-3333-3333-3333-000000000004'),
  ('55555555-5555-5555-5555-000000004001', '44444444-4444-4444-4444-000000000004', 'Fire Safety Inspection Fee', '15% of all fees charged by the city. The lowest fee is ₱500. If the city''s fees are zero, this fee is zero. Ask BFP Pasig for the full list of documents.', '33333333-3333-3333-3333-000000000005'),
  ('55555555-5555-5555-5555-000000005001', '44444444-4444-4444-4444-000000000005', 'Valid government ID', 'Bring a valid ID with your photo and signature.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005002', '44444444-4444-4444-4444-000000000005', 'Unified Business Application Form', 'Fill in the form. It is free to download.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005003', '44444444-4444-4444-4444-000000000005', 'DTI or SEC certificate', 'Bring your DTI certificate, or your SEC certificate with Articles. Cooperatives bring their CDA (Cooperative Development Authority) certificate.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005004', '44444444-4444-4444-4444-000000000005', 'Barangay Business Clearance', 'Bring the original and a clear photocopy.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005005', '44444444-4444-4444-4444-000000000005', 'Certificate of Conformance', 'The one you got in Step 3.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005006', '44444444-4444-4444-4444-000000000005', 'Fire Safety Inspection Certificate for Occupancy', 'The one you got in Step 4. Only if your place is newly built or renovated.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005007', '44444444-4444-4444-4444-000000000005', 'Proof of business location', 'A notarized lease or sub-lease contract, or a land title or Tax Declaration.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005008', '44444444-4444-4444-4444-000000000005', 'Color photo of your business place', 'Front view, in 2R size (2.5" x 3.5").', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005009', '44444444-4444-4444-4444-000000000005', 'Location map', 'A map of your business place, in 2R size (2.5" x 3.5").', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000005010', '44444444-4444-4444-4444-000000000005', 'Authorization letter and ID', 'Only if someone else applies for you. Bring a letter and a valid ID with photo and signature.', '33333333-3333-3333-3333-000000000006'),
  ('55555555-5555-5555-5555-000000006001', '44444444-4444-4444-4444-000000000006', 'Validated application form and documents', 'These are checked and returned to you in Step 5.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000007001', '44444444-4444-4444-4444-000000000007', 'Tax Order of Payment', 'The paper you got in Step 6. The total depends on your business.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000008001', '44444444-4444-4444-4444-000000000008', 'Sanitary Permit', 'Needed by all shops and businesses. Ask the City Health Department Environmental Sanitation Section.', '33333333-3333-3333-3333-000000000008'),
  ('55555555-5555-5555-5555-000000008002', '44444444-4444-4444-4444-000000000008', 'Health Certificate for food workers', 'Costs ₱70, including a ₱20 seminar fee. This is already in your Tax Order of Payment. Pay ₱50 more if your check-up was not done at the Pasig One Stop Shop Clinic (5th floor). Ask the City Health Department which tests you need.', '33333333-3333-3333-3333-000000000008'),
  ('55555555-5555-5555-5555-000000008003', '44444444-4444-4444-4444-000000000008', 'Health Certificate', 'Costs ₱70, including a ₱20 seminar fee. This is already in your Tax Order of Payment. Pay ₱50 more if your check-up was not done at the Pasig One Stop Shop Clinic (5th floor). If you sell food, ask the City Health Department which tests you need.', '33333333-3333-3333-3333-000000000008'),
  ('55555555-5555-5555-5555-000000008004', '44444444-4444-4444-4444-000000000008', 'Health Certificate', 'Costs ₱70, including a ₱20 seminar fee. This is already in your Tax Order of Payment. Pay ₱50 more if your check-up was not done at the Pasig One Stop Shop Clinic (5th floor). Ask the City Health Department which tests you need.', '33333333-3333-3333-3333-000000000008'),
  ('55555555-5555-5555-5555-000000008005', '44444444-4444-4444-4444-000000000008', 'Pest control contract', 'Food businesses may need a pest control contract. Confirm this at the City Health Department.', '33333333-3333-3333-3333-000000000008'),
  ('55555555-5555-5555-5555-000000008006', '44444444-4444-4444-4444-000000000008', 'Environmental clearance from CENRO', 'Only if your business makes waste, uses harmful materials, or may cause pollution. The fee is already in your Tax Order of Payment. Ask CENRO (City Environment and Natural Resources Office) which papers you need.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000008007', '44444444-4444-4444-4444-000000000008', 'Fire Safety Inspection Permit for your business permit', 'This is a different certificate from Step 4. The fee is 10% of the regulatory fees on your Tax Order of Payment. Apply on the BFP Fire Safety Inspection System website.', '33333333-3333-3333-3333-000000000005'),
  ('55555555-5555-5555-5555-000000009001', '44444444-4444-4444-4444-000000000009', 'Certificate of Conformance', 'If your place is in a mall or in the Ortigas Center, ask the office if you still need this.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000009002', '44444444-4444-4444-4444-000000000009', 'Fire Safety Inspection Certificate', 'The valid one from Step 8.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000009003', '44444444-4444-4444-4444-000000000009', 'CENRO clearance', 'Valid. Ask CENRO if your business needs one.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000009004', '44444444-4444-4444-4444-000000000009', 'Sanitary Permit', 'The valid one from Step 8.', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-000000009005', '44444444-4444-4444-4444-000000000009', 'Application form, Tax Order of Payment, and cedula', 'Bring your own copy of the application form, the current Tax Order of Payment, and your cedula (Community Tax Certificate).', '33333333-3333-3333-3333-000000000009'),
  ('55555555-5555-5555-5555-00000010a001', '44444444-4444-4444-4444-00000000010a', 'BIR Form 1901', 'Fill it in online. If you apply in person, bring 2 original signed copies.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a002', '44444444-4444-4444-4444-00000000010a', 'Valid government ID', 'Bring 1 photocopy of a valid ID with your photo, full name, address, and birth date. For example a PhilID, driver''s license, passport, or UMID. If your ID has no address, also bring 1 photocopy of proof of your home or business address in your name. If a PRC (Professional Regulation Commission) license applies to you, bring 1 photocopy of your PRC ID and a government ID that shows your address.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a003', '44444444-4444-4444-4444-00000000010a', 'DTI Certificate of Business Name Registration', 'Bring 1 photocopy of the certificate from Step 1A. Bring it only if you use a business name.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a004', '44444444-4444-4444-4444-00000000010a', 'Mayor''s Permit or Business Permit', 'Bring 1 photocopy of the permit from Step 9. Some Revenue District Offices may accept your Barangay Clearance instead. Ask your office.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a005', '44444444-4444-4444-4444-00000000010a', 'Invoice option (choose one)', 'Option A: buy BIR printed invoices at the RDO counter. Option B: bring 1 original, final, clear sample of the invoices or receipts you want to print, for printer accreditation.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a006', '44444444-4444-4444-4444-00000000010a', 'Documentary stamp tax', '₱30. If you apply in person, bring it as a loose stamp for your Certificate of Registration (BIR Form 2303). If you apply online, pay it online after you are approved.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a007', '44444444-4444-4444-4444-00000000010a', 'Special Power of Attorney and IDs', 'Only if someone else applies for you. Bring 1 original Special Power of Attorney (SPA) that names the transaction. Also bring 1 photocopy of a valid ID of you and your representative, with sample signatures.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a008', '44444444-4444-4444-4444-00000000010a', 'Work visa or Alien Employment Permit', 'Only if you are a foreign national. Bring 1 photocopy of your 9(g) Work Visa or Alien Employment Permit (AEP).', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a009', '44444444-4444-4444-4444-00000000010a', 'DTI Certificate of Authority for BMBE', 'Only if your business is a BMBE (Barangay Micro Business Enterprise). Bring 1 photocopy of your DTI (Department of Trade and Industry) Certificate of Authority.', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a010', '44444444-4444-4444-4444-00000000010a', 'Proof of registration or Permit to Operate', 'Only if your business is tax-exempt or has special benefits. Bring 1 photocopy from BOI (Board of Investments), PEZA (Philippine Economic Zone Authority), TIEZA (Tourism Infrastructure and Enterprise Zone Authority), or SBMA (Subic Bay Metropolitan Authority).', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010a011', '44444444-4444-4444-4444-00000000010a', 'Franchise documents', 'Only if you run a common carrier (public transport). Bring 1 photocopy of your franchise papers, for example a Certificate of Public Convenience from the LTFRB (Land Transportation Franchising and Regulatory Board).', '33333333-3333-3333-3333-000000000011'),
  ('55555555-5555-5555-5555-00000010b001', '44444444-4444-4444-4444-00000000010b', 'BIR Form 1903', 'Fill it in online. If you apply in person, bring 2 original copies signed by an authorized officer of your company.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b002', '44444444-4444-4444-4444-00000000010b', 'SEC Certificate of Incorporation', 'Bring 1 photocopy of the certificate you got in Step 1B.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b003', '44444444-4444-4444-4444-00000000010b', 'SEC Certificate of Recording', 'Bring 1 photocopy of the certificate you got in Step 1B.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b004', '44444444-4444-4444-4444-00000000010b', 'Articles and By-Laws', 'Bring 1 photocopy.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b005', '44444444-4444-4444-4444-00000000010b', 'Articles of Partnership', 'Bring 1 photocopy.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b006', '44444444-4444-4444-4444-00000000010b', 'Mayor''s Permit or Business Permit', 'Bring 1 photocopy of the permit from Step 9. It must be under your company name.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b007', '44444444-4444-4444-4444-00000000010b', 'Proof of business address', 'Bring 1 photocopy of your lease contract, or your Transfer Certificate of Title (TCT), under your company name.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b008', '44444444-4444-4444-4444-00000000010b', 'Invoice option (choose one)', 'Option A: buy BIR printed invoices at the RDO counter. Option B: bring 1 original, final, clear sample of the invoices or receipts your company wants to print.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b009', '44444444-4444-4444-4444-00000000010b', 'Documentary stamp tax', '₱30. If you apply in person, bring it as a loose stamp for your Certificate of Registration (BIR Form 2303). If you apply online, pay it online after you are approved.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b010', '44444444-4444-4444-4444-00000000010b', 'Special Power of Attorney and IDs', 'Only if someone else applies for you. Bring 1 original Special Power of Attorney (SPA) that names the transaction. Also bring 1 photocopy of a valid ID of both the company''s authorized officer and your representative, with sample signatures.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b011', '44444444-4444-4444-4444-00000000010b', 'Work visa or Alien Employment Permit', 'Only if the applicant is a foreign national. Bring 1 photocopy of the 9(g) Work Visa or Alien Employment Permit (AEP).', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b012', '44444444-4444-4444-4444-00000000010b', 'DTI Certificate of Authority for BMBE', 'Only if your business is a BMBE (Barangay Micro Business Enterprise). Bring 1 photocopy of your DTI (Department of Trade and Industry) Certificate of Authority.', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b013', '44444444-4444-4444-4444-00000000010b', 'Proof of registration or Permit to Operate', 'Only if your business is tax-exempt or has special benefits. Bring 1 photocopy from BOI (Board of Investments), PEZA (Philippine Economic Zone Authority), TIEZA (Tourism Infrastructure and Enterprise Zone Authority), or SBMA (Subic Bay Metropolitan Authority).', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-00000010b014', '44444444-4444-4444-4444-00000000010b', 'Franchise documents', 'Only if you run a common carrier (public transport). Bring 1 photocopy of your franchise papers, for example a Certificate of Public Convenience from the LTFRB (Land Transportation Franchising and Regulatory Board).', '33333333-3333-3333-3333-000000000012'),
  ('55555555-5555-5555-5555-000000005011', '44444444-4444-4444-4444-000000000005', 'If your business is a restaurant, fast food, canteen, eatery, or catering service that deals with animal meat: Veterinary Clearance from the Pasig City Department of Veterinary Services.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005012', '44444444-4444-4444-4444-000000000005', 'If your business is a restobar, night club, or beer house: stay 200 meters away from public offices, schools, and churches. Bring Health Certificates for your workers, a Working Permit for each worker, and a Fire Safety Certificate.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005013', '44444444-4444-4444-4444-000000000005', 'If your business is a water refilling station: Certification of Water Potability from the City Health Department, or a Certification of Sanitary Inspection.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005014', '44444444-4444-4444-4444-000000000005', 'If your business makes food or beauty products: FDA (Food and Drug Administration) License.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005015', '44444444-4444-4444-4444-000000000005', 'If your business is a pharmacy or drugstore: FDA (Food and Drug Administration) License.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005016', '44444444-4444-4444-4444-000000000005', 'If your business is a pet shop: Animal Certification of Registration from the Bureau of Animal Industry, and Veterinary Clearance from the Pasig City Department of Veterinary Services.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005017', '44444444-4444-4444-4444-000000000005', 'If your business is an LPG dealer or gasoline station: DOE (Department of Energy) Accreditation.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005018', '44444444-4444-4444-4444-000000000005', 'If your business is a pawnshop, money changer, or remittance agency: Certification to Operate from the Bangko Sentral ng Pilipinas.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005019', '44444444-4444-4444-4444-000000000005', 'If your business is an electronics or electrical equipment shop: DTI (Department of Trade and Industry) Accreditation Certificate.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005020', '44444444-4444-4444-4444-000000000005', 'If your business is an auto repair, electronics, or radio repair shop: DTI (Department of Trade and Industry) Accreditation Certificate.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005021', '44444444-4444-4444-4444-000000000005', 'If your business is a junkshop, vulcanizing shop, carwash, or auto repair shop: a lot of at least 100 square meters, plus the lot title or your lease contract and the owner''s TCT.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005022', '44444444-4444-4444-4444-000000000005', 'If your business exercises a profession: PRC (Professional Regulation Commission) License and PTR (Professional Tax Receipt).', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005023', '44444444-4444-4444-4444-000000000005', 'If your business is a travel agency: DOT (Department of Tourism) Accreditation.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005024', '44444444-4444-4444-4444-000000000005', 'If your business is a school or training center: DepEd (Department of Education) or CHED (Commission on Higher Education) Accreditation.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005025', '44444444-4444-4444-4444-000000000005', 'If your business is a recruitment or manpower agency: License to Operate from DOLE (Department of Labor and Employment) or POEA, as the case may be.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005026', '44444444-4444-4444-4444-000000000005', 'If your business is a rent-a-car or transport service: LTO (Land Transportation Office) Franchise.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005027', '44444444-4444-4444-4444-000000000005', 'If your business is a real estate lessor: Proof of Ownership.', NULL, '33333333-3333-3333-3333-000000000007'),
  ('55555555-5555-5555-5555-000000005028', '44444444-4444-4444-4444-000000000005', 'If your business is a warehouse or depot: Certification that says what kind of goods you will store.', NULL, '33333333-3333-3333-3333-000000000007');
